validations.command:
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
let now = 0, next = 0;
const jobs = new Map();
const timers = { schedule(fn, delay) { const id = ++next; jobs.set(id, {fn, at: now + delay}); return id; }, cancel(id) { jobs.delete(id); } };
function advance(ms) { now += ms; for (const [id, job] of [...jobs]) if (job.at <= now) { jobs.delete(id); job.fn(); } }
const store = createDraftStore();
const writes = [];
store.subscribe(e => writes.push(e));
const archive = createReceiptArchive();
const notices = [];
let api;
api = createWorkspace({store, archive, timers, renderDocument() {}, renderStatus() {}, renderSubmission: r => notices.push(r), onSaved(e, nav) { if (e.text === 'switch') nav.open('b'); }});
api.open('a'); api.edit('one'); advance(100); api.edit('two'); advance(119);
assert.equal(writes.length, 0); advance(1);
assert.deepEqual(writes.map(e => e.text), ['two']);
api.edit('three'); advance(120);
assert.deepEqual(writes.map(e => e.text), ['two', 'three']);
api.edit('four'); const receipt = api.submit();
assert.deepEqual(receipt, {id:'a', text:'four'});
assert.equal(store.read('a'), 'four');
api.edit('five'); api.close(); assert.equal(store.read('a'), 'five');
api.open('a'); assert.equal(api.submit().text, 'five');
api.edit('switch'); api.open('c');
assert.equal(store.read('a'), 'switch');
assert.equal(api.submit().id, 'b');
advance(500); assert.equal(writes.filter(e => e.text === 'switch').length, 1);
console.log('focused checks passed');
EOF
